export default "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<feed xmlns:yt=\"http://www.youtube.com/xml/schemas/2015\" xmlns:media=\"http://search.yahoo.com/mrss/\" xmlns=\"http://www.w3.org/2005/Atom\">\n <link rel=\"self\" href=\"http://www.youtube.com/feeds/videos.xml?channel_id=UCLA_DiR1FfKNvjuUpBHmylQ\"/>\n <id>yt:channel:LA_DiR1FfKNvjuUpBHmylQ</id>\n <yt:channelId>LA_DiR1FfKNvjuUpBHmylQ</yt:channelId>\n <title>NASA</title>\n <link rel=\"alternate\" href=\"https://www.youtube.com/channel/UCLA_DiR1FfKNvjuUpBHmylQ\"/>\n <author>\n  <name>NASA</name>\n  <uri>https://www.youtube.com/channel/UCLA_DiR1FfKNvjuUpBHmylQ</uri>\n </author>\n <published>2008-06-03T18:44:30+00:00</published>\n <entry>\n  <id>yt:video:ivng4U5xeYM</id>\n  <yt:videoId>ivng4U5xeYM</yt:videoId>\n  <yt:channelId>UCLA_DiR1FfKNvjuUpBHmylQ</yt:channelId>\n  <title>NASA's SpaceX Crew-12 Postflight News Conference (Oct. 15, 2026)</title>\n  <link rel=\"alternate\" href=\"https://www.youtube.com/watch?v=ivng4U5xeYM\"/>\n  <author>\n   <name>NASA</name>\n   <uri>https://www.youtube.com/channel/UCLA_DiR1FfKNvjuUpBHmylQ</uri>\n  </author>\n  <published>2026-10-15T20:12:26+00:00</published>\n  <updated>2026-10-18T21:47:55+00:00</updated>\n  <media:group>\n   <media:title>NASA's SpaceX Crew-12 Postflight News Conference (Oct. 15, 2026)</media:title>\n   <media:content url=\"https://www.youtube.com/v/ivng4U5xeYM?version=3\" type=\"application/x-shockwave-flash\" width=\"640\" height=\"390\"/>\n   <media:thumbnail url=\"https://i2.ytimg.com/vi/ivng4U5xeYM/hqdefault.jpg\" width=\"480\" height=\"360\"/>\n   <media:description>After spending over seven months in space, members of NASA’s SpaceX Crew-12 will discuss their mission aboard the International Space Station during a news conference at the agency’s Johnson Space Center in Houston.\n\nNASA astronauts Jessica Meir and Jack Hathaway, ESA (European Space Agency) astronaut Sophie Adenot, and Roscosmos cosmonaut Andrey Fedyaev returned to Earth on Oct. 8, after spending 237 days living and working in orbit. (Adenot will return to Europe and not be available during the news conference.)\n\nLearn more about Crew-12's science and technology research: https://go.nasa.gov/4jdAre7\n\nWatch Crew-12's return to Earth: https://youtube.com/live/x6p9Ri0DlNE\n\nRead more about Crew-12's return and today's event: https://go.nasa.gov/3UikER9</media:description>\n   <media:community>\n    <media:starRating count=\"955\" average=\"5.00\" min=\"1\" max=\"5\"/>\n    <media:statistics views=\"90022\"/>\n   </media:community>\n  </media:group>\n </entry>\n<entry>\n  <id>yt:video:UleiRdWFG7o</id>\n  <yt:videoId>UleiRdWFG7o</yt:videoId>\n  <yt:channelId>UCLA_DiR1FfKNvjuUpBHmylQ</yt:channelId>\n  <title>U.S. Spacewalk Preview News Conference (Oct. 20, 2026)</title>\n  <link rel=\"alternate\" href=\"https://www.youtube.com/watch?v=UleiRdWFG7o\"/>\n  <author>\n   <name>NASA</name>\n   <uri>https://www.youtube.com/channel/UCLA_DiR1FfKNvjuUpBHmylQ</uri>\n  </author>\n  <published>2026-10-15T16:05:48+00:00</published>\n  <updated>2026-10-16T13:55:34+00:00</updated>\n  <media:group>\n   <media:title>U.S. Spacewalk Preview News Conference (Oct. 20, 2026)</media:title>\n   <media:content url=\"https://www.youtube.com/v/UleiRdWFG7o?version=3\" type=\"application/x-shockwave-flash\" width=\"640\" height=\"390\"/>\n   <media:thumbnail url=\"https://i2.ytimg.com/vi/UleiRdWFG7o/hqdefault.jpg\" width=\"480\" height=\"360\"/>\n   <media:description>We're giving a preview of two upcoming spacewalks on Oct. 29 and Nov. 5 to finish installing solar arrays that will provide more power to the International Space Station. \n\nNASA astronaut Anil Menon and CSA (Canadian Space Agency) astronaut Joshua Kutryk will participate in both spacewalks. The spacewalks will be the 285th and 286th conducted in support of space station assembly, maintenance, and upgrades.\n\nNASA participants in the news conference include:\n- Gaurang Patel, operations integration manager, Low Earth Orbit Program\n- Garrett Hehn, spacewalk flight director, Flight Operations Directorate\n\nLearn more about the spacewalks: https://go.nasa.gov/4yRBm97\nLearn more about International Space Station operations and research: https://www.nasa.gov/station</media:description>\n   <media:community>\n    <media:starRating count=\"101\" average=\"5.00\" min=\"1\" max=\"5\"/>\n    <media:statistics views=\"0\"/>\n   </media:community>\n  </media:group>\n </entry>\n</feed>\n"
